						CommUtils.outred("$name in ${currentState.stateName} | $currentMsg | ${Thread.currentThread().getName()} n=${Thread.activeCount()}")
						 	   
						if( checkMsgContent( Term.createTerm("stepfailed(DURATION,CAUSE)"), Term.createTerm("stepfailed(DURATION,CAUSE)"), 
						                        currentMsg.msgContent()) ) { //set msgArgList
								CommUtils.outblack("Errore o ostacolo incontrato, Causa: ${payloadArg(1)}")
								 
								                PianoFallito = MossaCorrente + PianoRimanente 
						}
						answer("doplan", "doplanfailed", "doplanfailed($PianoFallito)"   )  
						//genTimer( actor, state )
					}
					//After Lenzi Aug2002
					sysaction { //it:State
					}	 	 
					 transition(edgeName="t06",targetState="piano",cond=whenRequest("doplan"))
				}	 
				state("pianoFinito") { //this:State
					action { //it:State
						CommUtils.outgreen("$name in ${currentState.stateName} | $currentMsg | ${Thread.currentThread().getName()} n=${Thread.activeCount()}")
						 	   
						CommUtils.outblack("Intera sequenza di passi eseguita con successo.")
						answer("doplan", "doplandone", "doplandone(success)"   )  
						//genTimer( actor, state )
					}
					//After Lenzi Aug2002
					sysaction { //it:State
					}	 	 
					 transition(edgeName="t07",targetState="piano",cond=whenRequest("doplan"))
